#!/usr/bin/env bash
# ============================================================================
# 昇腾算子模拟环境 · WSL Ubuntu 22.04 引导脚本
#
# 用途：在一个干净的 Ubuntu 22.04 (WSL2) 里装好 Ascend C 算子开发所需的
#       系统依赖 + CANN Toolkit（CPU 域孪生调试 / NPU 仿真模式所需）。
#       全程不需要昇腾实体卡。
#
# 用法（由 scripts/ascend.ps1 bootstrap 自动调用，也可手动执行）：
#   wsl -d AscendCANN -u root -- bash /work/env/wsl/bootstrap.sh
#
# 幂等：重复执行会跳过已安装的包与已安装的 CANN。
# ============================================================================
set -euo pipefail

CONF="/work/env/cann.env"
[[ -f "$CONF" ]] || CONF="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/cann.env"
# shellcheck disable=SC1090
source "$CONF"

LOG_PREFIX="[bootstrap]"
log()  { printf '\033[1;32m%s %s\033[0m\n' "$LOG_PREFIX" "$*"; }
warn() { printf '\033[1;33m%s %s\033[0m\n' "$LOG_PREFIX" "$*"; }
die()  { printf '\033[1;31m%s %s\033[0m\n' "$LOG_PREFIX" "$*" >&2; exit 1; }

[[ $EUID -eq 0 ]] || die "请以 root 运行（WSL 默认 root 即可）"

# ---------------------------------------------------------------- 1. apt 源
if ! grep -q 'mirrors.aliyun.com' /etc/apt/sources.list 2>/dev/null; then
    log "切换 apt 源到阿里云镜像"
    cp -a /etc/apt/sources.list /etc/apt/sources.list.bak
    sed -i \
        -e 's|http://archive.ubuntu.com/ubuntu|https://mirrors.aliyun.com/ubuntu|g' \
        -e 's|http://security.ubuntu.com/ubuntu|https://mirrors.aliyun.com/ubuntu|g' \
        -e 's|http://cn.archive.ubuntu.com/ubuntu|https://mirrors.aliyun.com/ubuntu|g' \
        /etc/apt/sources.list
fi

export DEBIAN_FRONTEND=noninteractive
log "apt-get update"
apt-get update -qq

# ------------------------------------------------------- 2. 系统依赖
# 说明：build-essential/cmake 用于编译；gdb 用于 CPU 域孪生调试；
#       python3 用于 golden 比对脚本；其余为 CANN 安装器依赖检查项。
APT_PKGS=(
    build-essential cmake gcc g++ gdb make pkg-config
    python3 python3-pip python3-dev python3-venv
    git curl wget unzip zip file vim less
    libssl-dev zlib1g-dev libsqlite3-dev libffi-dev
    libblas-dev liblapack-dev
    bc rsync sudo ca-certificates
)
log "安装系统依赖（apt）"
apt-get install -y -qq "${APT_PKGS[@]}" >/dev/null

log "gcc: $(gcc -dumpfullversion -dumpversion)  cmake: $(cmake --version | head -1 | awk '{print $3}')  python: $(python3 -V)"

# ------------------------------------------------------- 3. CANN Toolkit
# CANN 9.x 的目录布局是 $CANN_INSTALL_PATH/cann；旧版本是 .../ascend-toolkit，两者都兼容
find_set_env() {
    for p in "$CANN_INSTALL_PATH/cann/set_env.sh" \
             "$CANN_INSTALL_PATH/ascend-toolkit/set_env.sh"; do
        [[ -f "$p" ]] && { echo "$p"; return 0; }
    done
    return 1
}
CANN_ENV_SH="$(find_set_env || true)"
if [[ -n "$CANN_ENV_SH" ]]; then
    log "CANN 已安装：$CANN_ENV_SH（跳过安装）"
else
    RUNNER="$(ls /work/.cache/cann/Ascend-cann-toolkit_${CANN_VERSION}_linux-x86_64.run 2>/dev/null || true)"
    if [[ -z "$RUNNER" ]]; then
        warn "本地未找到安装包，开始下载 CANN ${CANN_VERSION}"
        mkdir -p /work/.cache/cann
        curl -fL --retry 3 -o "/work/.cache/cann/Ascend-cann-toolkit_${CANN_VERSION}_linux-x86_64.run" \
             "$CANN_TOOLKIT_URL"
        RUNNER="/work/.cache/cann/Ascend-cann-toolkit_${CANN_VERSION}_linux-x86_64.run"
    fi
    # 从 drvfs 直接执行安装器容易踩 noexec/权限问题，复制到 /opt 再执行
    log "安装 CANN ${CANN_VERSION}（约 3~8 分钟）"
    mkdir -p /opt/cann-install
    cp -f "$RUNNER" /opt/cann-install/cann.run
    chmod +x /opt/cann-install/cann.run
    /opt/cann-install/cann.run --install --quiet --install-path="$CANN_INSTALL_PATH" \
        || die "CANN 安装失败，查看 /opt/cann-install 与 $CANN_INSTALL_PATH 下的日志"
    rm -f /opt/cann-install/cann.run
fi

# ------------------------------------------------- 4. 环境变量持久化
CANN_ENV_SH="$(find_set_env || true)"
cat > /etc/profile.d/ascend-cann.sh <<EOF
# Ascend CANN environment (generated by env/wsl/bootstrap.sh)
if [ -f "${CANN_ENV_SH}" ]; then
    . "${CANN_ENV_SH}"
fi
EOF
chmod +x /etc/profile.d/ascend-cann.sh

# ------------------------------------------------- 5. /work ASCII 软链
# Windows 工作区路径含中文，部分工具链对非 ASCII 路径敏感，统一用 /work 访问。
if [[ ! -e /work ]]; then
    ln -s "$WORKSPACE_WSL" /work
    log "创建软链 /work -> $WORKSPACE_WSL"
fi

log "完成。验证："
# shellcheck disable=SC1091
. /etc/profile.d/ascend-cann.sh
echo "  ASCEND_HOME_PATH = ${ASCEND_HOME_PATH:-<未设置>}"
echo "  ascendc          = $(command -v ascendc || echo '<未找到>')"
echo "  bisheng          = $(command -v bisheng || echo '<未找到>')"
echo "  现在可以跑: bash /work/env/check_env.sh"
